def decode_string(s):
    index = 0
    def parse():
        nonlocal index
        pieces = []
        while index<len(s) and s[index]!=']':
            if s[index].isdigit():
                count = 0
                while s[index].isdigit():
                    count = count*10+int(s[index])
                    index += 1
                index += 1
                segment = parse()
                index += 1
                pieces.append(segment*count)
            else:
                pieces.append(s[index])
                index += 1
        return ''.join(pieces)
    return parse()

